def typed(name):
 if name in {"reviewer_id", "created_by", "reported_by", "submitted_by", "requested_by", "owner_label"}: return ref("label")
 if name.endswith("_digest") or name.endswith("_sha256") or name.endswith("_hash"): return ref("sha")
 if name.endswith("_id") or name in {"registry_id","package_id","policy_id","record_id","report_id","diff_id","consumer_id","snapshot_id","release_id","environment_id","pointer_id","attestation_id","head_id","review_id","action_id","execution_id"}: return ref("id")
 if name.endswith("_iris") or name in {"affected_terms","required_term_iris"}: return ref("iris")
 if name.endswith("_iri"): return ref("iri")
 if name.endswith("_version") or name in {"base_version","candidate_version"}: return ref("version")
 if name in {"package_name","registry_name","consumer_name","environment_name"}: return ref("name")
 if name=="observed_at": return ref("time")
 if name in {"sequence","archive_size_bytes","activation_quorum","rollback_quorum","minimum_distinct_reviewers"}: return ref("positive")
 if name in {"generation","event_count","base_pointer_generation","old_generation","new_generation","required_test_count","optional_test_count"}: return ref("count")
 if name in {"resource_limits"}: return ref("queryLimits")
 if name in {"package_records","feedback_records","change_proposals","consumer_manifests","release_candidates","release_reviews","releases","environments","activation_proposals"}: return ref("projections")
 if name in {"artifact_refs","authority_records"}: return ref("artifactRefs")
 if name in {"identity_changes","tbox_changes","abox_changes","shacl_changes","mapping_changes","cq_changes","dependency_changes","annotation_changes","provenance_changes","metadata_changes"}: return ref("changes")
 if name=="raw_statement_delta": return ref("rawDelta")
 if name=="classification_summary": return ref("classificationCounts")
 if name=="tests": return ref("tests")
 if name=="checks": return ref("checks")
 if name=="issues": return ref("issues")
 if name in {"feedback_refs","required_competency_questions","source_domain_pack_lock_ids","allowed_package_names","required_mapping_ids","required_cq_ids","environment_refs","release_lineage","related_ids","affected_packages","affected_releases","affected_consumers","affected_environments","affected_mappings","domain_pack_locks"}: return ref("ids")
 if name=="accepted_package_format_versions": return ref("versions")
 if name in {"observations","requested_outcomes","constraints","blocking_reasons","review_requirements","unknown_constructs","regression_requirements","verification_evidence","prohibited_operations","package_import_policy","immutability_policy","component_policies","classification_rules","review_roles","alternative_roles","required_roles","role_coverage","allowed_release_types","activation_roles","rollback_roles","required_acknowledgements"}: return ref("labels")
 if name=="actions": return arr({"type":"object","additionalProperties":True},10000)
 if name=="metric_records": return ref("metrics")
 if name=="query_contracts": return ref("queries")
 if name=="nodes": return ref("nodes")
 if name=="edges": return ref("edges")
 if name=="illegal_cycles": return ref("cycles")
 if name=="migration_requirements": return ref("migrations")
 if name=="package_constraints": return ref("packageConstraints")
 if name=="quorum_rules": return ref("quorumRules")
 if name=="authority_digests": return ref("authorityDigests")
 if name=="summary": return ref("testSummary")
 if name in {"compatible","quorum_satisfied","finalized","breaking_change_acknowledged","production_authority","explicit_human_action"}: return {"type":"boolean"}
 if name=="risk_summary": return obj({"overall":{"enum":["LOW","MEDIUM","HIGH","CRITICAL","UNKNOWN"]},"reasons":ref("texts")})
 if name=="payload": return ref("eventPayload")
 return {"type":["string","number","boolean","object","array","null"]}
